     1	package hotel.documents;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.format.DateTimeFormatter;
     6	import java.util.Locale;
     7	
     8	/** How money and dates are written in the texts the guest reads (Brazilian Portuguese). */
     9	public final class TextFormat {
    10	
    11	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
    12	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    13	
    14	    private TextFormat() {
    15	    }
    16	
    17	    public static String money(BigDecimal amount) {
    18	        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
    19	    }
    20	
    21	    public static String date(LocalDate date) {
    22	        return BRAZILIAN_DATE.format(date);
    23	    }
    24	}
    25	package hotel.reservations;
    26	
    27	import hotel.rooms.Room;
    28	import java.math.BigDecimal;
    29	import java.math.RoundingMode;
    30	import java.time.LocalDate;
    31	import java.time.Month;
    32	
    33	/**
    34	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    35	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    36	 * (half-even) at every step.
    37	 */
    38	public final class PriceCalculator {
    39	
    40	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    41	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    42	
    43	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    44	        int nights = 0;
    45	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    46	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    47	            subtotal = subtotal.add(nightPrice(room, night));
    48	            nights++;
    49	        }
    50	        BigDecimal discount = switch (ratePlan) {
    51	            case STANDARD -> cents(BigDecimal.ZERO);
    52	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    53	        };
    54	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    55	    }
    56	
    57	    BigDecimal nightPrice(Room room, LocalDate night) {
    58	        BigDecimal nightlyRate = room.nightlyRate();
    59	        if (isHighSeason(night)) {
    60	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    61	        }
    62	        return cents(nightlyRate);
    63	    }
    64	
    65	    /** High season: from December 15 to the end of February, and the whole of July. */
    66	    static boolean isHighSeason(LocalDate date) {
    67	        Month month = date.getMonth();
    68	        return month == Month.JANUARY
    69	                || month == Month.FEBRUARY
    70	                || month == Month.JULY
    71	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    72	    }
    73	
    74	    static BigDecimal cents(BigDecimal value) {
    75	        return value.setScale(2, RoundingMode.HALF_EVEN);
    76	    }
    77	}
