   127	package hotel.reservations;
   128	
   129	/**
   130	 * Who stays and how they are identified: a CPF, or a company (CNPJ and name), or a passport and country. Exactly
   131	 * one of the three is filled; the other fields are null.
   132	 */
   133	public record Guest(
   134	        String name,
   135	        String email,
   136	        String cpf,
   137	        String companyCnpj,
   138	        String companyName,
   139	        String passport,
